 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    g = [row[:] for row in grid]
    # Locate the 1-shape and the multicolor key strip.
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    if not pts:
        return g
    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
    shape = [(r-r0, c-c0) for r, c in pts]
    # A solid rectangular strip of non-background/non-shape colors encodes the sequence.
    nonzero = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] not in (0, 1)]
    if not nonzero:
        return g
    rows = sorted(set(r for r,c,v in nonzero)); cols = sorted(set(c for r,c,v in nonzero))
    if len(rows) >= len(cols):
        colors = [grid[rows[0]][c] for c in cols]
    else:
        colors = [grid[r][cols[0]] for r in rows]
    # Put the copy corresponding to color 1 where the given motif is; sequence order follows the key.
    try: idx = colors.index(1)
    except ValueError: idx = len(colors)//2
    dh, dw = r1-r0+1, c1-c0+1
    top = r0 - idx*dh
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in (0,):
                g[r][c] = 0
    for k, color in enumerate(colors):
        for dr, dc in shape:
            rr, cc = top+k*dh+dr, c0+dc
            if 0 <= rr < h and 0 <= cc < w:
                g[rr][cc] = color
    return g
